use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let str_input = input.as_str().unwrap();
    let mut sum = 0;
    let mut has_two_digits = false;

    for c in str_input.chars() {
        let digit = c.to_digit(10).unwrap();
        if digit >= 0 && digit <= 9 {
            sum += digit;
            if sum >= 10 {
                has_two_digits = true;
                sum = 0;
            }
        }
    }

    if has_two_digits {
        Value::Bool(true)
    } else {
        Value::Bool(false)
    }
}
